create view IF NOT EXISTS CART_ADDITIONS(
	DATASETID,
	TIMESTAMP,
	FULLVISITORID,
	SESSIONID,
	SESSIONNUMBER,
	EVENTCATEGORY,
	EVENTACTION,
	HITNUMBER,
	PRODUCTNAME,
	PRODUCTPRICE,
	QUANTITY,
	CARTORDER
) as (
    SELECT
        distinct
        dataset_Id as DatasetId,
        TO_CHAR(to_timestamp(VisitStartTime), 'MM/DD/YYYY HH24:MI:SS.FF3') as Timestamp,
        FullVisitorId as FullVisitorId,
        VisitId::string as SessionId,
        VisitNumber::string as SessionNumber,
        hits_eventInfo_eventCategory as EventCategory,
        hits_eventInfo_eventAction as EventAction,
        hits_hitNumber as HitNumber,
        hits_product_v2ProductName as ProductName,
        hits_product_productPrice/POW(10,6) as ProductPrice, -- by default in source hits_product_productPrice is multiplied by 10^6 (e.g., 2.40 would be given as 2400000)
        ifnull(hits_product_productQuantity::int, 1) as Quantity,
        DENSE_RANK() OVER (PARTITION BY SessionNumber, SessionId, Timestamp, FullVisitorId ORDER BY HitNumber) as CartOrder
    FROM HIT
    WHERE
        (hits_eventinfo_eventAction = 'Add to Cart' AND  hits_eventInfo_eventCategory = 'Order')
        OR (hits_eventinfo_eventAction = 'Add Item' AND hits_eventInfo_eventCategory = 'Cart')
        AND hits_eventInfo_eventAction IS NOT NULL

    UNION

    SELECT
        distinct
        dataset_Id as DatasetId,
        to_char(to_timestamp(LEFT(event_timestamp, 13)), 'MM/DD/YYYY HH:MM:SS.FF3') as Timestamp, -- microseconds converted to milliseconds
        user_pseudo_id as FullVisitorId,
        IFF(LEN("'ga_session_id'") = 0, 'NULL',"'ga_session_id'")  as SessionId,
        IFF(LEN("'ga_session_number'") = 0, 'NULL', "'ga_session_number'") as SessionNumber,
        event_name as EventCategory,
        event_name as EventAction,
        NULL as HitNumber, -- not provided in GA_EVENTS, that's why all column has NULLs
        items_item_name as ProductName,
        items_price as ProductPrice,
        "'quantity'"::int as Quantity,
        DENSE_RANK() OVER (PARTITION BY SessionId, SessionNumber, FullVisitorId ORDER BY Timestamp) as CartOrder
    FROM GA_EVENTS
    PIVOT(listagg(event_params_value) for event_params_key in ('ga_session_id', 'ga_session_number', 'quantity')) as p
    WHERE event_name = 'add_to_cart'
);
create view IF NOT EXISTS CART_REMOVALS(
	DATASETID,
	TIMESTAMP,
	FULLVISITORID,
	SESSIONID,
	SESSIONNUMBER,
	EVENTCATEGORY,
	EVENTACTION,
	PRODUCTNAME,
	PRODUCTPRICE,
	QUANTITY
) as (
SELECT
    distinct
    dataset_Id as DatasetId,
    TO_CHAR(to_timestamp(VisitStartTime), 'MM/DD/YYYY HH24:MI:SS') as Timestamp,
    FullVisitorId as FullVisitorId,
    VisitId::string as SessionId,
    VisitNumber::string as SessionNumber,
    hits_eventInfo_eventCategory as EventCategory,
    hits_eventInfo_eventAction as EventAction,
    hits_product_v2ProductName as ProductName,
    hits_product_productPrice/POW(10,6) as ProductPrice, -- by default in source hits_product_productPrice is multiplied by 10^6 (e.g., 2.40 would be given as 2400000)
    IFNULL(hits_product_productQuantity::int, 1) as Quantity
FROM
    HIT_MV
WHERE
    hits_eventInfo_eventCategory = 'Cart'
    AND hits_eventInfo_eventAction = 'Remove'

UNION

SELECT
    distinct
    dataset_Id as DatasetId,
    TO_CHAR(to_timestamp(LEFT(event_timestamp, 13)), 'MM/DD/YYYY HH24:MI:SS') as Timestamp, -- microseconds converted to milliseconds
    user_pseudo_id as FullVisitorId,
    "'ga_session_id'" as SessionId,
    "'ga_session_number'" as SessionNumber,
    event_name as EventCategory,
    event_name as EventAction,
    items_item_name as ProductName,
    items_price as ProductPrice,
    "'quantity'"::int as Quantity
FROM
    ga_events_mv
    PIVOT(listagg(event_params_value) for event_params_key in ('ga_session_id', 'ga_session_number', 'quantity')) as p
WHERE
    event_name = 'remove_from_cart'
);
create view IF NOT EXISTS FINAL_PRODUCTS_PURCHASED(
	DATASET_ID,
	FULLVISITORID,
	SESSIONID,
	SESSIONNUMBER,
	TIMESTAMP,
	PRODUCTNAME,
	PRODUCTQUANTITY,
	IS_PROMO
) as (
SELECT *
FROM(
     SELECT DISTINCT
     H.dataset_Id as dataset_Id,
     H.FullVisitorId as FullVisitorId,
     H.VisitId::string as SessionId,
     H.VisitNumber::string as SessionNumber,
     TO_CHAR(DATEADD(
                millisecond,
                ZEROIFNULL(H.HITS_TIME),
                TO_TIMESTAMP(S.visitStartTime)
            ), 'MM/DD/YYYY HH24:MI:SS') as Timestamp,
     H.HITS_PRODUCT_V2PRODUCTNAME as ProductName,
     H.HITS_PRODUCT_PRODUCTQUANTITY as ProductQuantity,
     CASE WHEN UPPER(H.HITS_PRODUCT_V2PRODUCTNAME) LIKE ANY ('BOGO%', '%+%', '%LCS%', '%BUNDLE%', '%BUY%GET%') THEN 'Yes'
     ELSE 'No' END AS IS_PROMO -- all products containting this characters are considered a promo
     FROM HIT  as H
     join SESSION as S
     on H.VisitID = S.VisitID and
     H.VisitNumber = S.VisitNumber and
     H.FullVisitorID = S.FullVisitorID
     WHERE H.HITS_PRODUCT_V2PRODUCTNAME IS NOT NULL
     AND H.HITS_PRODUCT_PRODUCTQUANTITY IS NOT NULL
     AND H.HITS_TRANSACTION_TRANSACTIONID IS NOT NULL -- purchase is made only if there is transaction_id

    UNION

    SELECT DISTINCT
    dataset_Id,
    user_pseudo_id as FullVisitorId,
    "'ga_session_id'" as SessionId,
    "'ga_session_number'" as SessionNumber,
    TO_CHAR(to_timestamp(LEFT(event_timestamp, 13)), 'MM/DD/YYYY HH24:MI:SS') as Timestamp,
    items_item_name AS ProductName,
    items_quantity ProductQuantity,
    CASE WHEN UPPER(items_item_name) LIKE ANY ('BOGO%', '%+%', '%LCS%', '%BUNDLE%', '%BUY%GET%') THEN 'Yes'
    ELSE 'No' END AS IS_PROMO -- all products containting this characters are considered a promo
    FROM GA_EVENTS
    pivot(listagg(user_properties_value) for user_properties_key in ('ga_session_id','ga_session_number')) p
    WHERE event_name='ecommerce_purchase' -- in order to take only products which were purchased
    and items_item_name is not null and items_quantity is not null
 ));
create view IF NOT EXISTS FINAL_SALES_AMOUNTS(
	USER_ID,
	USER_PSEUDO_ID,
	GA_SESSION_ID,
	GA_SESSION_NUMBER,
	TRANSACTION_ID,
	DATE_UTC,
	HHMMSS,
	DATETIME,
	ISDELIVERY,
	PICKUPTIME,
	SHIPPING,
	TAX,
	TIP,
	SUBTOTAL,
	VALUE
) as (
with ecommerce_purchase_events as (
    SELECT distinct
    event_timestamp
    ,user_id
    ,user_pseudo_id
    ,user_properties_key
    ,user_properties_value
    ,event_params_key
    ,event_params_value
  FROM GA_EVENTS
  where
     event_name = 'ecommerce_purchase'
    and event_params_key IN ('tax', 'tip','shipping','value','isDelivery', 'pickuptime', 'transaction_id')
)
select
    user_id
    ,user_pseudo_id
    ,ga_session_id
    ,ga_session_number
    ,transaction_id
    ,TO_DATE(TO_TIMESTAMP(event_timestamp::string)) AS DATE_UTC
    ,TO_TIME(TO_TIMESTAMP(event_timestamp::string)) AS HHMMSS
    ,TO_TIMESTAMP(event_timestamp::string) AS DATETIME
    ,isDelivery
    ,pickuptime
    ,shipping
    ,tax
    ,tip
    ,(value-tax-shipping-tip) as subtotal
    ,value
from ecommerce_purchase_events
pivot(listagg(event_params_value) for event_params_key in ('isDelivery', 'pickuptime', 'shipping', 'tax','tip','value','transaction_id'))
p1 (event_timestamp, user_id, user_pseudo_id, user_properties_key, user_properties_value, isDelivery, pickuptime, shipping, tax, tip, value, transaction_id)
pivot(listagg(user_properties_value) for user_properties_key in ('ga_session_id','ga_session_number'))
p2 (event_timestamp, user_id, user_pseudo_id, isDelivery, pickuptime, shipping, tax, tip, value, transaction_id, ga_session_id, ga_session_number)
)
/*
Source is GA_EVENTS as specified in the task. In case event_name=ecommerce_purchase the row describes the 
purchase, so only those rows are of interest.
From event_params_value collected value meaning depends on the event_params_key. The mapping used:
  event_params_key=tax -> tax value
  event_params_key=tip -> tip value
  event_params_key=shipping -> shipping value
  event_params_key=value -> total value
  event_params_key=isDelivery -> is delivery ( true/false values)
  event_params_key=pickuptime -> time of delivery or pickup depends on isDelivery
  event_params_key=transaction_id -> transaction id
Subtotal is calculated as value-tax-shipping-tip.
From user_properties_value collected value meaning depends on user_properties_key. The mapping used:
  user_properties_key=ga_session_id -> ga_session_id
  user_properties_key=ga_session_number -> ga_session_number
ga_session_id and ga_session_number are used to uniquely define the session.
More info can be found in the task description https://inspirebrands.atlassian.net/browse/DD-107
*/;
create view IF NOT EXISTS GA_CUSTOMERS_EPSILON_USERS_VAPP(
	FULLVISITORID,
	VISITID,
	VISITNUMBER,
	DATE,
	USERID,
	PROFILE_ID,
	PROFILEGUID,
	MEMBER_PHONENUMBER,
	FIRST_NAME,
	LAST_NAME,
	EMAIL_ADDRESS
) as (
SELECT      GS.FULLVISITORID,
            GS.VISITID::string visitid,
            GS.VISITNUMBER,
            GS.DATE,
            ANY_VALUE(GS.USERID) as userid,
            ANY_VALUE(LM.Profile_Id) as Profile_Id,
            ANY_VALUE(lm.profileguid) as profileguid,
            ANY_VALUE(LM.Member_PhoneNumber) as Member_PhoneNumber,
            ANY_VALUE(LM.First_Name) as First_Name,
            ANY_VALUE(LM.Last_name) as Last_name,
            ANY_VALUE(LM.Email_Address) as Email_Address
FROM "SESSION" as GS
INNER JOIN "LOYALTY_MEMBER" as LM on GS.Userid = LM.ProfileGUID
WHERE GS.UserID IS NOT NULL
GROUP BY 1, 2, 3, 4);
