create view IF NOT EXISTS SESSION_SUMMARY_VAPP(
	FULL_VISITOR_ID,
	VISIT_NUMBER,
	VISIT_ID,
	DATE,
	USERID,
	PROFILE_ID,
	PROFILEGUID,
	MEMBER_PHONENUMBER,
	FIRST_NAME,
	LAST_NAME,
	EMAIL_ADDRESS,
	CHANNELGROUPING,
	TRAFFICSOURCE_MEDIUM,
	TRAFFICSOURCE_SOURCE,
	TRAFFICSOURCE_CAMPAIGN,
	SESSION_START_TIME_UTC,
	SESSION_START_DATE_UTC,
	SESSION_START_HHMMSS_UTC,
	SESSION_END_TIME_UTC,
	SESSION_DURATION,
	LOCAL_TIMEZONE,
	SESSION_START_TIME_LOCAL,
	SESSION_END_TIME_LOCAL,
	LOAD_ID,
	LOAD_DATE,
	DATASET_ID,
	STORENUMBER
) as (
SELECT
    FULL_VISITOR_ID,
    VISIT_NUMBER,
    VISIT_ID,
    DATE,
    USERID,
    PROFILE_ID,
    PROFILEGUID,
    MEMBER_PHONENUMBER,
