    END_SESSION_DATETIME AS SESSION_END_TIME_UTC,
    SESSION_DURATION,
    store.TIMEZONE AS LOCAL_TIMEZONE,
    RDS_DEV.IRB.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(SESSION_START_TIME_UTC, LOCAL_TIMEZONE) AS SESSION_START_TIME_LOCAL,
    RDS_DEV.IRB.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(SESSION_END_TIME_UTC, LOCAL_TIMEZONE) AS SESSION_END_TIME_LOCAL,
    sh.LOAD_ID,
    LOAD_DATE,
    DATASET_ID,
    StoreNumber
from(
select
    S.FULL_VISITOR_ID,
    S.VISIT_NUMBER,
    S.VISIT_ID,
    S.DATE,
    S.USERID,
    S.PROFILE_ID,
    S.PROFILEGUID,
    S.MEMBER_PHONENUMBER,
    S.FIRST_NAME,
    S.LAST_NAME,
    S.EMAIL_ADDRESS,
    S.CHANNELGROUPING,
    S.TRAFFICSOURCE_MEDIUM,
    S.TRAFFICSOURCE_SOURCE,
    S.TRAFFICSOURCE_CAMPAIGN,
    S.START_SESSION_DATETIME_UTC,
    S.START_SESSION_DATE_UTC,
    S.START_SESSION_HHMMSS_UTC,
    S.END_SESSION_DATETIME,
    S.SESSION_DURATION,
    S.LOAD_ID,
    S.LOAD_DATE,
    S.DATASET_ID,
    CASE WHEN S.DATASET_ID in ('126099547','241143169') THEN S.Store_Number ELSE H.Store_Number END AS StoreNumber
from TRANSFORM_SESSION_CAMPAIGN_BY_SESSION as S
left join TRANSFORM_SESSION_CAMPAIGN_BY_HIT as H
on  H.Visit_ID = S.Visit_ID
