	START_SESSION_DATETIME_UTC,
	START_SESSION_DATE_UTC,
	START_SESSION_HHMMSS_UTC,
	END_SESSION_DATETIME,
	SESSION_DURATION,
	LOCAL_TIMEZONE,
	STARTSESSIONLOCALDATETIME,
	ENDSESSIONLOCALDATETIME,
