    SESSION_DURATION,
    store.TIMEZONE AS LOCAL_TIMEZONE,
    RDS_DEV.IRB.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(START_SESSION_DATETIME_UTC, LOCAL_TIMEZONE) AS StartSessionLocalDatetime,
    RDS_DEV.IRB.CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE(END_SESSION_DATETIME, LOCAL_TIMEZONE) AS EndSessionLocalDatetime,
    sh.LOAD_ID,
