    S.USERID,
    S.PROFILE_ID,
    S.PROFILEGUID,
    S.MEMBER_PHONENUMBER,
    S.FIRST_NAME,
    S.LAST_NAME,
    S.EMAIL_ADDRESS,
    S.CHANNELGROUPING,
    S.TRAFFICSOURCE_MEDIUM,
    S.TRAFFICSOURCE_SOURCE,
    S.TRAFFICSOURCE_CAMPAIGN,
    S.START_SESSION_DATETIME_UTC,
    S.START_SESSION_DATE_UTC,
    S.START_SESSION_HHMMSS_UTC,
    S.END_SESSION_DATETIME,
    S.SESSION_DURATION,
    S.LOAD_ID,
    S.LOAD_DATE,
    S.DATASET_ID,
    CASE WHEN S.DATASET_ID in ('126099547','241143169') THEN S.Store_Number ELSE H.Store_Number END AS StoreNumber
from "RDS_DEV"."BWW"."TRANSFORM_SESSION_CAMPAIGN_BY_SESSION" as S
left join "RDS_DEV"."BWW"."TRANSFORM_SESSION_CAMPAIGN_BY_HIT" as H
on  H.Visit_ID = S.Visit_ID
and H.Visit_Number = S.Visit_Number
and H.Full_Visitor_ID = S.Full_Visitor_ID
 ) sh
LEFT JOIN RDS_DEV.IRB.STORE_DIM store on sh.StoreNumber = store.STORE_KEY::STRING and store.BRAND_ID='bww');
create view IF NOT EXISTS TRANSFORM_SESSION_CAMPAING_VAPP(
	FULL_VISITOR_ID,
	VISIT_NUMBER,
	VISIT_ID,
	DATE,
	SITE_CATEGORY,
	SOURCE_SITE,
	SOURCE_EMAIL,
	START_SESSION_DATETIME,
	START_SESSION_DATE_UTC,
	START_SESSION_HHMMSS,
	END_SESSION_DATETIME,
	SESSION_DURATION,
	LOAD_ID,
	LOAD_DATE
) as (
SELECT
    S.FULLVISITORID as FULL_VISITOR_ID,
    S.VISITNUMBER as VISIT_NUMBER,
    S.VisitId::string as VISIT_ID,
    S.DATE,
    ANY_VALUE(S.channelgrouping) as SITE_CATEGORY,
    ANY_VALUE(S.TrafficSource_source) as SOURCE_SITE,
    ANY_VALUE(Session_email.TRAFFICSOURCE_CAMPAIGN) as SOURCE_EMAIL,
    ANY_VALUE(TO_TIMESTAMP(S.visitStartTime)) as START_SESSION_DATETIME,
    ANY_VALUE(TO_TIMESTAMP(S.visitStartTime)) as START_SESSION_DATE_UTC,
    ANY_VALUE(TO_TIMESTAMP(S.visitStartTime)) as START_SESSION_HHMMSS,
    ANY_VALUE(
        DATEADD(
            second,
            ZEROIFNULL(S.totals_timeOnSite),
            TO_TIMESTAMP(S.visitStartTime)
        )
    ) as END_SESSION_DATETIME,
    ANY_VALUE(ZEROIFNULL(S.totals_timeOnSite)) AS SESSION_DURATION,
    ANY_VALUE(S.LOAD_ID) as LOAD_ID,
    ANY_VALUE(S.LOAD_DATE) as LOAD_DATE
FROM
    SESSION S
    LEFT JOIN (
        SELECT
            FullVisitorID,
            VisitNumber,
            VisitID,
            Date,
            TRAFFICSOURCE_CAMPAIGN
        FROM
            SESSION
        WHERE
            channelGrouping = 'Email'
    ) as Session_email ON S.FullVisitorID = Session_email.FullVisitorID
    AND S.Date = Session_email.Date
    AND S.VisitNumber = Session_email.VisitNumber
    AND S.VisitID = Session_email.VisitID
GROUP BY 1, 2, 3, 4);
