CREATE FUNCTION IF NOT EXISTS ARRAY_UNION_DISTINCT("ARRAY1" ARRAY, "ARRAY2" ARRAY)
RETURNS ARRAY
LANGUAGE JAVA
HANDLER = 'ArrayUnionDistinctUdf.perform'
TARGET_PATH = '@TEST_STAGE/ArrayUnionDistinctUdf.jar'
AS '
    import java.util.stream.Stream;
    class ArrayUnionDistinctUdf {
        public static String[] perform(String[] x, String[] y) {
          Stream<String> concat = Stream.concat(Stream.of(x),Stream.of(y));
          return concat.distinct().toArray(java.lang.String[]::new);
        }
    }
';
CREATE FUNCTION IF NOT EXISTS CONVERT_OBJECT_VALUEZEKA("A" ARRAY)
RETURNS ARRAY
LANGUAGE JAVASCRIPT
AS '
    const FLEXIBLE_KEY_NAMES = ["string_value", "int_value", "double_value", "float_value"]

    const parseInput = (input = {}) => {
        const res = {
            "key": input.key
        };
        const value = input.value;
        if (value) {
            for (const [key, value] of Object.entries(input.value)) {
                if (FLEXIBLE_KEY_NAMES.includes(key)) {
                    res.value = value;
                } else {
                    res[key] = value;
                }
            }
        }
        return res;
    }

    return A.map(parseInput)
  ';
CREATE FUNCTION IF NOT EXISTS CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE("T" TIMESTAMP_NTZ(9), "TIME_ZONE" VARCHAR(16777216))
RETURNS TIMESTAMP_NTZ(9)
LANGUAGE JAVASCRIPT
AS '
    const time_zone_dict = {
        ''Central Standard Time'': ''America/Chicago'',
        ''Eastern Standard Time'': ''America/Detroit'',
        ''Pacific Standard Time'': ''America/Los_Angeles'',
        ''Mountain Standard Time'': ''America/Denver'',
        ''Atlantic Standard Time'': ''America/Barbados'',
        ''Alaskan Standard Time'': ''America/Anchorage'',
        ''Hawaiian Standard Time'': ''Pacific/Honolulu''
    };
    if(!TIME_ZONE) return null
    return new Date(new Date(T + "+00:00").toLocaleString("en-US", {timeZone: time_zone_dict[TIME_ZONE]})).getTime()
  ';
CREATE FUNCTION IF NOT EXISTS CONVERT_TIMESTAMP_FROM_UTC_TO_TIMEZONE("T" VARCHAR(16777216), "TIME_ZONE" VARCHAR(16777216))
RETURNS TIMESTAMP_NTZ(9)
LANGUAGE JAVASCRIPT
AS '
    const time_zone_dict = {
        ''Central Standard Time'': ''America/Chicago'',
        ''Eastern Standard Time'': ''America/Detroit'',
        ''Pacific Standard Time'': ''America/Los_Angeles'',
        ''Mountain Standard Time'': ''America/Denver'',
        ''Atlantic Standard Time'': ''America/Barbados'',
        ''Alaskan Standard Time'': ''America/Anchorage'',
        ''Hawaiian Standard Time'': ''Pacific/Honolulu''
    };

    return new Date(new Date(T + "+00:00").toLocaleString("en-US", {timeZone: time_zone_dict[TIME_ZONE]})).getTime()
  ';
