CREATE PROCEDURE IF NOT EXISTS SANJA_TEST_RESULT_SCAN()
RETURNS VARCHAR(16777216)
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS '
  var rs = snowflake.execute( { sqlText: 
      `select * from table(result_scan(last_query_id())) ;`
       } );
  return ''rs'';
  ';
